 $bridge=[Reflection.Emit.DynamicMethod]::new('EncodingTry'+$Direction+$Write,[bool],$signature);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$sourceType.GetConstructor([type[]]@($sourceArray,[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$destinationType.GetConstructor([type[]]@($destinationArray,[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]7);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$definition=[type]('System.Func`'+($signature.Count+1));return $bridge.CreateDelegate($definition.MakeGenericType([type[]]@($signature+[bool])))
}
function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index}elseif($e -is [Text.DecoderFallbackException]){$r.unknownBytes=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('GenericTrySpanProbe'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('probe');$builder=$module.DefineType('GenericSpanEncoding',[Reflection.TypeAttributes]'Public,Sealed',[Text.Encoding]);$fields=@{};foreach($name in @('Multiplier','CountMode','WriteMode')){$fields[$name]=$builder.DefineField($name,[int],[Reflection.FieldAttributes]::Public)};$fields.Trace=$builder.DefineField('Trace',[Collections.Generic.List[int[]]],[Reflection.FieldAttributes]::Public)
$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@());$il=$constructor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,[type[]]@(),$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)
foreach($abstract in [Text.Encoding].GetMethods()|Where-Object IsAbstract){$parameters=[type[]]@($abstract.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($abstract.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',$abstract.ReturnType,$parameters);$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback intercepted');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,$abstract)}
$roDefinition=[type]'System.ReadOnlySpan`1';$spanDefinition=[type]'System.Span`1'
foreach($direction in @('Encoder','Decoder')){foreach($write in @($false,$true)){$encode=$direction -eq 'Encoder';$src=if($encode){[char]}else{[byte]};$dst=if($encode){[byte]}else{[char]};$ro=$roDefinition.MakeGenericType([type[]]@($src));$span=$spanDefinition.MakeGenericType([type[]]@($dst));$name=if($encode){if($write){'GetBytes'}else{'GetByteCount'}}else{if($write){'GetChars'}else{'GetCharCount'}};[type[]]$parameters=if($write){[type[]]@($ro,$span)}else{[type[]]@($ro)};$method=$builder.DefineMethod($name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',[int],$parameters);$il=$method.GetILGenerator();$n=$il.DeclareLocal([int]);$cap=$il.DeclareLocal([int]);$mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$notThrow=$il.DefineLabel();$notNegative=$il.DefineLabel()
 $il.Emit([Reflection.Emit.OpCodes]::Ldarga_S,[byte]1);$il.Emit([Reflection.Emit.OpCodes]::Call,$ro.GetProperty('Length').GetMethod);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$n);if($write){$il.Emit([Reflection.Emit.OpCodes]::Ldarga_S,[byte]2);$il.Emit([Reflection.Emit.OpCodes]::Call,$span.GetProperty('Length').GetMethod)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1)};$il.Emit([Reflection.Emit.OpCodes]::Stloc,$cap)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Trace);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_3);$il.Emit([Reflection.Emit.OpCodes]::Newarr,[int]);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$(if($encode){if($write){1}else{0}}else{if($write){3}else{2}}));$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$n);$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$cap);$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[Collections.Generic.List[int[]]].GetMethod('Add'))
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$cap);$il.Emit([Reflection.Emit.OpCodes]::Brfalse,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldarga_S,[byte]2);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Call,$span.GetProperty('Item').GetMethod);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($encode){[Reflection.Emit.OpCodes]::Stind_I1}else{[Reflection.Emit.OpCodes]::Stind_I2}));$il.MarkLabel($normal)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$notThrow);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'span callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($notThrow);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$notNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($notNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$n);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_3);$il.Emit([Reflection.Emit.OpCodes]::Ceq);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($method,[Text.Encoding].GetMethod($name,$parameters))
}}
$type=$builder.CreateType();$bridges=@{Encoder=(Bridge 'Encoder' $true);Decoder=(Bridge 'Decoder' $true)};$rows=[Collections.Generic.List[object]]::new()
foreach($direction in @('Encoder','Decoder')){foreach($multiplier in @(1,3)){foreach($countMode in 0..3){foreach($writeMode in 0..3){foreach($length in @(0,1,3,7)){foreach($capacity in @(0,1,2,3,4,8,32)){foreach($offset in @(0,2)){$encoding=[Activator]::CreateInstance($type);foreach($pair in @(@('Multiplier',$multiplier),@('CountMode',$countMode),@('WriteMode',$writeMode))){$type.GetField($pair[0]).SetValue($encoding,[int]$pair[1])};$trace=[Collections.Generic.List[int[]]]::new();$type.GetField('Trace').SetValue($encoding,$trace);$sourceValue=if($direction -eq 'Encoder'){,[char[]]::new($length+2)}else{,[byte[]]::new($length+2)};$target=if($direction -eq 'Encoder'){,[byte[]]::new($capacity+$offset+2)}else{,[char[]]::new($capacity+$offset+2)};for($i=0;$i -lt $target.Length;$i++){$target[$i]=99};$written=[int[]]@(-7)
 try{$success=$bridges[$direction].Invoke($encoding,$sourceValue,1,$length,$target,$offset,$capacity,$written);$result=[ordered]@{ok=$true;success=$success}}catch{$result=Failure $_.Exception};$rows.Add([ordered]@{direction=$direction;multiplier=$multiplier;countMode=$countMode;writeMode=$writeMode;length=$length;capacity=$capacity;offset=$offset;result=$result;written=$written[0];destination=[int[]]$target;trace=$trace.ToArray()})
}}}}}}}
